@sig trait Readiness_Evidence_Derivation_Api {
  def id: Art.BridgeId
  def charge_decision_Id : Art.PortId
  def battery_evidence_Id : Art.PortId
  def readiness_evidence_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var readiness_evidence: Drone_Battery_Charge_Supervisor.BatteryReadinessEvidence.Type = $

  def put_readiness_evidence(value : Drone_Battery_Charge_Supervisor.BatteryReadinessEvidence.Type) : Unit = {
    Contract(
      Modifies(readiness_evidence),
      Ensures(
        readiness_evidence == value
      )
    )
    Spec {
      readiness_evidence = value
    }

    Art.putValue(readiness_evidence_Id, Drone_Battery_Charge_Supervisor.BatteryReadinessEvidence_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class Readiness_Evidence_Derivation_Initialization_Api (
  val id: Art.BridgeId,
  val charge_decision_Id : Art.PortId,
  val battery_evidence_Id : Art.PortId,
  val readiness_evidence_Id : Art.PortId) extends Readiness_Evidence_Derivation_Api

